__NUXT_JSONP__("/kr/school-calendar", {data:[{details:{slug:"kr",pageTitle:"학교 달력 | Mentor Language Institute",pageDescription:"프로그램 시작일은 학생비자(F1) 또는 그 외의 비자에 따라 다양합니다.",title:"학교 달력",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003E노란색 \u003C\u002Ffont\u003E: 프로그램 시작 일 (Module)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003E초록색 \u003C\u002Ffont\u003E： 휴강일 (휴일)"],schoolCalendar:{title:"학교 달력 (프로그램 시작일)",description:["\u003Cspan class=\"ymarker\"\u003E프로그램 시작일은 학생비자(F1) 또는 그 외의 비자에 따라 다양합니다.\u003C\u002Fspan\u003E"],lists:[{key:"학생비자(F1)를 소지하지 않은 학생",value:["매주 월요일에 프로그램을 시작할 수 있습니다. \u003Cbr\u003E 월요일이 공휴일인 경우 프로그램 시작일은 해당 주의 화요일입니다."]},{key:"학생비자(F1)을 소지한 학생",value:["지정된 월요일에 프로그램을 시작할 수 있습니다. (달력 상의 노란색으로 표시) ","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"미국 도착 날짜에 대해 자주 묻는 질문",lists:[{key:"\u003Cb\u003E질문: 프로그램 시작 며칠 전부터 미국에 입국이 가능한가요?\u003C\u002Fb\u003E",value:["답변: MLI는 사전에 학생들에게 특정 날짜를 지정하여 미국에 입국할 것을 요구하지 않습니다. 다만, 본교 학생들은 대부분 프로그램 시작일로부터 하루 이틀 전에 미국으로 입국합니다."],note:"참고: 국제학생들은 학교 프로그램 시작일 30일 전부터 입국하는 것이 허용됩니다."},{key:"\u003Cb\u003E질문: 프로그램 시작일 전부터 숙소에 입주할 수 있나요?\u003C\u002Fb\u003E",value:["답변: 네. 희망하시는 일자로 숙소 입주일을 잡아드릴 수 있습니다.\u003Cbr \u002F\u003E다른 궁금하신 사항이나 질문 등이 있으시다면 언제든 연락주시기 바랍니다."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fkr",extension:".json",createdAt:"2026-10-22T16:31:30.877Z",updatedAt:"2026-04-24T11:47:24.323Z"}}],fetch:{},mutations:void 0});